                        new
                        {
                            Id = new Guid("d3100000-0000-4000-8000-000000000003"),
                            Format = "article",
                            ItemsJson = "[{\"Id\":1,\"Prompt\":\"What is the main idea?\",\"Prefix\":\"\",\"MissingLetters\":0,\"Options\":[{\"Id\":\"A\",\"Text\":\"Gold is always more informative than pottery\"},{\"Id\":\"B\",\"Text\":\"Chemical tests eliminate uncertainty\"},{\"Id\":\"C\",\"Text\":\"Pottery and its context together reveal past activities\"},{\"Id\":\"D\",\"Text\":\"Broken objects should be discarded\"}],\"Answer\":\"C\",\"Explanation\":\"Both the material and the context of its discovery provide evidence about past lives.\"},{\"Id\":2,\"Prompt\":\"What might chemical analysis reveal?\",\"Prefix\":\"\",\"MissingLetters\":0,\"Options\":[{\"Id\":\"A\",\"Text\":\"The name of the pot\\u0027s owner\"},{\"Id\":\"B\",\"Text\":\"Food or drink residues\"},{\"Id\":\"C\",\"Text\":\"The exact date of every scratch\"},{\"Id\":\"D\",\"Text\":\"The value of gold\"}],\"Answer\":\"B\",\"Explanation\":\"The second paragraph explicitly mentions food and drink residues.\"},{\"Id\":3,\"Prompt\":\"Why are possible alternative explanations mentioned?\",\"Prefix\":\"\",\"MissingLetters\":0,\"Options\":[{\"Id\":\"A\",\"Text\":\"To show why several observations are needed\"},{\"Id\":\"B\",\"Text\":\"To reject all chemical testing\"},{\"Id\":\"C\",\"Text\":\"To prove every pot was buried deliberately\"},{\"Id\":\"D\",\"Text\":\"To explain why records are unnecessary\"}],\"Answer\":\"A\",\"Explanation\":\"Different possible causes of residues and scratches show why a single observation is insufficient.\"},{\"Id\":4,\"Prompt\":\"The word \\u0027these\\u0027 in \\u0027these relationships\\u0027 refers to\",\"Prefix\":\"\",\"MissingLetters\":0,\"Options\":[{\"Id\":\"A\",\"Text\":\"Chemical substances\"},{\"Id\":\"B\",\"Text\":\"Improved methods\"},{\"Id\":\"C\",\"Text\":\"Golden ornaments\"},{\"Id\":\"D\",\"Text\":\"Connections between vessels and their surroundings\"}],\"Answer\":\"D\",\"Explanation\":\"The preceding sentence describes different uses of vessels in homes and shared spaces.\"},{\"Id\":5,\"Prompt\":\"What can be inferred about careful records?\",\"Prefix\":\"\",\"MissingLetters\":0,\"Options\":[{\"Id\":\"A\",\"Text\":\"They prevent new interpretations\"},{\"Id\":\"B\",\"Text\":\"They are useful only to the first researcher\"},{\"Id\":\"C\",\"Text\":\"They allow evidence to be reconsidered later\"},{\"Id\":\"D\",\"Text\":\"They replace the need to preserve objects\"}],\"Answer\":\"C\",\"Explanation\":\"The final paragraph explains how new methods can test earlier interpretations.\"}]",
                            Module = "academic-passage",
                            Position = 3,
                            PublicationStatus = 2,
                            Text = "A broken cooking pot may appear less impressive than a golden ornament, yet it can provide rich evidence about everyday life. Pottery survives in many environments, and even small fragments can preserve traces of how a vessel was made and used. Researchers examine both the material itself and the place where it was discovered.\n\nChemical analysis may reveal residues left by food or drink. Marks on the surface can suggest repeated contact with fire or particular tools. Neither kind of evidence offers a complete story on its own. A substance could have entered the pot after it was discarded, while a scratch might have occurred during burial. Researchers therefore compare several independent observations before proposing an explanation.\n\nLocation is equally important. Similar vessels found in homes and in communal spaces may have served different purposes. If an object is removed without a record of its surroundings, these relationships can be lost. Careful documentation makes it possible for later researchers to test earlier interpretations using improved methods. Preserving information about an object's context can consequently be as valuable as preserving the object itself.",
                            Title = "The evidence inside pottery",
                            Version = 1
                        },
