                            Format = "paragraph",
                            ItemsJson = "[{\"Id\":1,\"Prompt\":\"Complete the missing letters.\",\"Prefix\":\"pl\",\"MissingLetters\":3,\"Options\":[],\"Answer\":\"ace\",\"Explanation\":\"The complete word is \\u0022place\\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods.\"},{\"Id\":2,\"Prompt\":\"Complete the missing letters.\",\"Prefix\":\"acr\",\"MissingLetters\":3,\"Options\":[],\"Answer\":\"oss\",\"Explanation\":\"The complete word is \\u0022across\\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods.\"},{\"Id\":3,\"Prompt\":\"Complete the missing letters.\",\"Prefix\":\"surf\",\"MissingLetters\":4,\"Options\":[],\"Answer\":\"aces\",\"Explanation\":\"The complete word is \\u0022surfaces\\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods.\"},{\"Id\":4,\"Prompt\":\"Complete the missing letters.\",\"Prefix\":\"mea\",\"MissingLetters\":4,\"Options\":[],\"Answer\":\"sure\",\"Explanation\":\"The complete word is \\u0022measure\\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods.\"},{\"Id\":5,\"Prompt\":\"Complete the missing letters.\",\"Prefix\":\"posi\",\"MissingLetters\":5,\"Options\":[],\"Answer\":\"tions\",\"Explanation\":\"The complete word is \\u0022positions\\u0022 in this sentence: Scientists place markers across frozen surfaces and measure their positions each summer while satellite images reveal broader patterns over longer periods.\"},{\"Id\":6,\"Prompt\":\"Complete the missing letters.\",\"Prefix\":\"sum\",\"MissingLetters\":3,\"Options\":[],\"Answer