            modelBuilder.Entity("ToeflExam.Infrastructure.Persistence.Entities.StudentSettings", b =>
                {
                    b.Property<string>("UserId")
                        .HasMaxLength(450)
                        .HasColumnType("nvarchar(450)");

                    b.Property<int>("DailyPracticeMinutes")
                        .HasColumnType("int");

                    b.Property<string>("DisplayName")
                        .IsRequired()
                        .HasMaxLength(100)
                        .HasColumnType("nvarchar(100)");

                    b.Property<DateOnly?>("TargetTestDate")
                        .HasColumnType("date");

                    b.HasKey("UserId");

                    b.ToTable("StudentSettings", "learning", t =>
                        {
                            t.HasCheckConstraint("CK_StudentSettings_Goal", "[DailyPracticeMinutes] BETWEEN 5 AND 180");
                        });
                });

